// Node: Check Market Open (Watchdog)
// Returns empty (stops execution) if market is closed or weekend.
// Market hours: 9:30 AM – 4:00 PM ET (EDT = UTC-4)

const now = new Date();
const utcMin = now.getUTCHours() * 60 + now.getUTCMinutes();
const dow    = now.getUTCDay(); // 0=Sun, 6=Sat

// 9:30 AM ET = 13:30 UTC | 4:00 PM ET = 20:00 UTC
if (dow < 1 || dow > 5 || utcMin < 810 || utcMin >= 1200) {
  return [{ json: { market_open: false, reason: 'Market closed', checked_at: now.toISOString() } }];
}

return [{ json: { market_open: true, checked_at: now.toISOString() } }];

// Node: Has Open Positions? (Watchdog)
// Maps open Alpaca positions to niches.
// Returns empty (stops execution) if no positions in our universe.
// Output: { open_niches, positions_by_niche, position_count, tickers_csv, raw_positions }

const TICKER_NICHE = {
  CRWD:'cybersecurity',PANW:'cybersecurity',ZS:'cybersecurity',OKTA:'cybersecurity',
  FTNT:'cybersecurity',S:'cybersecurity',CYBR:'cybersecurity',TMUS:'cybersecurity',
  QLYS:'cybersecurity',TENB:'cybersecurity',
  LMT:'defense',RTX:'defense',NOC:'defense',GD:'defense',HII:'defense',
  LHX:'defense',KTOS:'defense',RCAT:'defense',PLTR:'defense',AXON:'defense',
  CCJ:'nuclear_uranium',UEC:'nuclear_uranium',NXE:'nuclear_uranium',DNN:'nuclear_uranium',
  SMR:'nuclear_uranium',OKLO:'nuclear_uranium',CEG:'nuclear_uranium',VST:'nuclear_uranium',
  ETR:'nuclear_uranium',NEE:'nuclear_uranium',
  FCX:'copper_minerals',SCCO:'copper_minerals',TECK:'copper_minerals',HBM:'copper_minerals',
  VALE:'copper_minerals',MP:'copper_minerals',LTHM:'copper_minerals',ALB:'copper_minerals',
  SQM:'copper_minerals',LAC:'copper_minerals',
  NVDA:'ai_semiconductors',AMD:'ai_semiconductors',AVGO:'ai_semiconductors',
  QCOM:'ai_semiconductors',MRVL:'ai_semiconductors',AMAT:'ai_semiconductors',
  KLAC:'ai_semiconductors',LRCX:'ai_semiconductors',MU:'ai_semiconductors',ARM:'ai_semiconductors',
  MSFT:'cloud_hyperscalers',AMZN:'cloud_hyperscalers',GOOGL:'cloud_hyperscalers',
  META:'cloud_hyperscalers',ORCL:'cloud_hyperscalers',SNOW:'cloud_hyperscalers',
  MDB:'cloud_hyperscalers',DDOG:'cloud_hyperscalers',NET:'cloud_hyperscalers',CRM:'cloud_hyperscalers',
  XOM:'oil_gas',CVX:'oil_gas',COP:'oil_gas',SLB:'oil_gas',HAL:'oil_gas',
  MPC:'oil_gas',PSX:'oil_gas',VLO:'oil_gas',OXY:'oil_gas',EOG:'oil_gas',
  EQIX:'data_centers',DLR:'data_centers',AMT:'data_centers',IREN:'data_centers',
  CORZ:'data_centers',VRT:'data_centers',SMCI:'data_centers',DELL:'data_centers',
  HPE:'data_centers',WDC:'data_centers',
};

const raw       = $input.first().json;
const positions = Array.isArray(raw) ? raw
                : Array.isArray(raw && raw.body) ? raw.body
                : [];

if (positions.length === 0) {
  return [{ json: { has_positions: false, reason: 'No open Alpaca positions' } }];
}

const byNiche = {};
for (const pos of positions) {
  const niche = TICKER_NICHE[pos.symbol];
  if (!niche) continue;
  if (!byNiche[niche]) byNiche[niche] = { tickers: [], has_long: false, has_short: false };
  byNiche[niche].tickers.push(pos.symbol);
  if (parseFloat(pos.qty) > 0) byNiche[niche].has_long  = true;
  if (parseFloat(pos.qty) < 0) byNiche[niche].has_short = true;
}

const openNiches      = Object.keys(byNiche);
if (openNiches.length === 0) {
  return [{ json: { has_positions: false, reason: 'No positions in our 80-stock universe' } }];
}

const openPositions   = positions.filter(p => TICKER_NICHE[p.symbol]);
const tickers         = openPositions.map(p => p.symbol);

return [{ json: {
  has_positions:      true,
  open_niches:        openNiches,
  positions_by_niche: byNiche,
  position_count:     positions.length,
  tickers_csv:        tickers.join(','),  // used in Fetch Alpaca News URL: ?symbols=...
  raw_positions:      openPositions,      // full Alpaca objects for LLM context
} }];

// Node: Build News Prompt (Watchdog)
// Position: After Fetch Alpaca News HTTP node
// Input: $input = Alpaca news response { news: [...], next_page_token }
// Reads position context from $("Has Open Positions?") by name.
// Output: 1 item — { system_prompt, user_prompt } for the watchdog LLM call.

const newsRaw   = $input.first().json;
const articles  = newsRaw.news || [];
const posCtx    = $("Has Open Positions?").first().json;
const positions = posCtx.raw_positions || [];

// ── Format open positions ─────────────────────────────────────────────────────
function formatPositions(positions) {
  return positions.map(pos => {
    const qty     = parseFloat(pos.qty);
    const side    = qty > 0 ? 'LONG' : 'SHORT';
    const entry   = parseFloat(pos.avg_entry_price).toFixed(2);
    const current = parseFloat(pos.current_price).toFixed(2);
    const pnlPct  = (parseFloat(pos.unrealized_plpc) * 100).toFixed(2);
    const pnlAbs  = parseFloat(pos.unrealized_pl).toFixed(0);
    const sign    = parseFloat(pos.unrealized_pl) >= 0 ? '+' : '';
    return `${pos.symbol} (${side}) — Entry: $${entry} | Current: $${current} | P&L: ${sign}${pnlPct}% (${sign}$${pnlAbs})`;
  }).join('\n');
}

// ── Group headlines by ticker ─────────────────────────────────────────────────
function formatNews(articles, positions) {
  const byTicker = {};
  for (const pos of positions) byTicker[pos.symbol] = [];

  for (const a of articles) {
    for (const sym of (a.symbols || [])) {
      if (byTicker[sym] !== undefined) byTicker[sym].push(a);
    }
  }

  return Object.entries(byTicker).map(([ticker, arts]) => {
    if (arts.length === 0) return `=== ${ticker} ===\n  No recent headlines.`;
    const lines = arts.slice(0, 5).map((a, i) => {
      const ts = (a.created_at || '').substring(0, 16).replace('T', ' ');
      return `  [${i+1}] ${a.headline} (${ts})`;
    }).join('\n');
    return `=== ${ticker} ===\n${lines}`;
  }).join('\n\n');
}

// ── System prompt ─────────────────────────────────────────────────────────────
const SYSTEM_PROMPT = `You are a real-time news monitor for an AI-driven investment fund. You review breaking news headlines every 30 minutes and determine whether any headline materially changes the investment thesis for an open position.

## WHAT COUNTS AS THESIS-CHANGING
- Earnings results, revenue guidance revision, or profit warning
- Major contract win or loss (>5% of revenue impact)
- Regulatory action, government investigation, or sanctions
- CEO/CFO departure, fraud allegation, or accounting restatement
- Significant product failure, recall, or ban
- Acquisition, merger, or major strategic pivot announcement
- Geopolitical event directly targeting the company or its primary market

## WHAT DOES NOT CHANGE A THESIS
- Analyst price target adjustments (routine sell-side noise)
- General market commentary or macro outlook pieces
- Minor product announcements or conference participation
- Stock movement articles ("NVDA up 3% today") — price action alone is not a thesis change
- Repetitive earnings call headline fragments (already priced in)

## CALIBRATION — err on the side of thesis_intact: true
- confidence < 0.60 → thesis_intact: true (not enough signal to act)
- materiality: LOW → thesis_intact: true (not actionable)
- Triggering a false positive causes an unnecessary trade. When in doubt, leave it alone.

## OUTPUT FORMAT
Respond ONLY with valid JSON. No markdown, no backticks.

{
  "position_assessments": [
    {
      "ticker": "NVDA",
      "side": "LONG",
      "thesis_intact": true,
      "direction": "BULLISH | BEARISH | NEUTRAL",
      "confidence": 0.00,
      "materiality": "HIGH | MEDIUM | LOW",
      "key_headline": "The single most relevant headline, or null if none",
      "reasoning": "1-2 sentences"
    }
  ],
  "summary": "1 sentence — overall finding across all positions"
}`;

const userPrompt = `## OPEN POSITIONS
${formatPositions(positions)}

## BREAKING NEWS (last 30 min)
${formatNews(articles, positions)}

Review each position. For each, does any headline materially change the investment thesis?`;

return [{ json: { system_prompt: SYSTEM_PROMPT, user_prompt: userPrompt } }];

// Node: Parse Flip Response (Watchdog)
// Position: After watchdog LLM call (OpenAI v1.3 — { message: { content: "..." } })
// Parses LLM output, filters for actionable thesis flips.
// Returns empty (stops execution) if no flips meet the threshold.
// Output: 1 item with flip list → triggers orchestrator via Execute Workflow.

const raw     = $input.first().json;
const content = raw?.message?.content || raw?.choices?.[0]?.message?.content || '';

let parsed;
try {
  const jsonMatch = content.match(/\{[\s\S]*\}/);
  parsed = JSON.parse(jsonMatch ? jsonMatch[0] : content);
} catch (e) {
  return [{ json: { flips_detected: false, reason: 'LLM parse error', checked_at: new Date().toISOString() } }];
}

const assessments = parsed.position_assessments || [];

// Flip threshold: LLM says thesis broken + confidence ≥ 0.60 + not LOW materiality
const flips = assessments.filter(a =>
  a.thesis_intact === false &&
  (a.confidence  || 0) >= 0.60 &&
  a.materiality !== 'LOW'
);

if (flips.length === 0) {
  return [{ json: { flips_detected: false, checked_at: new Date().toISOString(), llm_summary: parsed.summary || null } }];
}

return [{
  json: {
    flips_detected: true,
    flip_count:     flips.length,
    flips,
    checked_at:     new Date().toISOString(),
    trigger_reason: `Thesis flip detected: ${flips.map(f => `${f.ticker} (${f.side})`).join(', ')}`,
    session_type:   'watchdog_flip',
    llm_summary:    parsed.summary || null,
  }
}];
